export function franceDebtSvg(lang,kind,mobile=false){
 if(typeof lang!=='string'||!['fr','en'].includes(lang)||typeof kind!=='string'||!FRANCE_DEBT_KINDS.includes(kind)||typeof mobile!=='boolean')throw new TypeError('Invalid France debt figure variant');
 return FIGURES[`${kind}-${lang}-${mobile?'mobile':'desktop'}`];
}
